#!/usr/bin/env bash
# Generated by install.sh — stops the local server.
set -euo pipefail
CONFIG_DIR="/Users/masontompkins/.config/creagent"
if [ -f "$CONFIG_DIR/server.pid" ]; then
  kill "$(cat "$CONFIG_DIR/server.pid")" 2>/dev/null && echo "Server stopped." || echo "Server was not running."
  rm -f "$CONFIG_DIR/server.pid"
else
  echo "Server was not running."
fi
if [ -f "$CONFIG_DIR/worker.pid" ]; then
  kill "$(cat "$CONFIG_DIR/worker.pid")" 2>/dev/null && echo "Worker stopped." || echo "Worker was not running."
  rm -f "$CONFIG_DIR/worker.pid"
else
  echo "Worker was not running."
fi
